import sys
import types

NS = types.SimpleNamespace
QUESTION = "How do I get VPN access as a contractor?"
corpus_ids = {"it/vpn-employees#1", "it/vpn-contractors#1", "it/vpn-contractors#2",
              "it/laptop-setup#1", "hr/badges#1"}
_RANKED = ["it/vpn-employees#1", "it/vpn-contractors#1", "it/laptop-setup#1"]


def retrieve(question, k):
    return [NS(id=i) for i in _RANKED[:k]]


def build_context(question, ranked):
    return NS(ids=ranked[:2])


def build_prompt(question):
    return "<context>VPN for employees: install the client.</context>\n" + question


wrong_answers = [
    {"question": QUESTION, "gold_id": "it/vpn-contractors#2"},
    {"question": "VPN for contractors?", "gold_id": "it/vpn-contractors#1"},
    {"question": "Parking for visitors?", "gold_id": "facilities/parking#1"},
    {"question": "Laptop for new hires?", "gold_id": "it/laptop-setup#1"},
]


def _create(*, model, max_tokens, messages, system=None, **kwargs):
    text = "Install the VPN client and sign in with your employee account."
    return NS(content=[NS(type="thinking", thinking=""), NS(type="text", text=text)],
              stop_reason="end_turn")


class _Anthropic:
    def __init__(self, **kwargs):
        self.messages = NS(create=_create)


sys.modules["anthropic"] = NS(Anthropic=_Anthropic)
